Inhalt von 'main.py':

import json
import os
import re
from datetime import datetime
import ollama

# 1. Pfade & Ordner
PROJECT_ROOT = os.path.dirname(os.path.abspath(__file__))
PROFILE_FILE = "user_profile.json"
HISTORY_DIR = "Chatverlauf"

if not os.path.exists(os.path.join(PROJECT_ROOT, HISTORY_DIR)):
    os.makedirs(os.path.join(PROJECT_ROOT, HISTORY_DIR))

def load_user_profile():
    profile_path = os.path.join(PROJECT_ROOT, PROFILE_FILE)
    if os.path.exists(profile_path):
        try:
            with open(profile_path, "r", encoding="utf-8") as f:
                data = json.load(f)
                if "updates" not in data:
                    data["updates"] = []
                return data
        except Exception:
            return {"updates": []}
    return {"updates": []}

user_data = load_user_profile()

def save_user_profile():
    profile_path = os.path.join(PROJECT_ROOT, PROFILE_FILE)
    try:
        with open(profile_path, "w", encoding="utf-8") as f:
            json.dump(user_data, f, ensure_ascii=False, indent=2)
        return True
    except Exception as e:
        print(f"[Fehler beim Speichern des Profils]: {e}")
        return False

# 2. Hilfsfunktionen (Werkzeuge/APIs)
def get_saved_files():
    history_path = os.path.join(PROJECT_ROOT, HISTORY_DIR)
    files = [
        os.path.join(history_path, f)
        for f in os.listdir(history_path)
        if f.endswith(".json")
    ]
    files.sort(key=os.path.getmtime, reverse=True)
    return files

def normalize_date(date_str):
    date_str = date_str.strip().replace(".", "-")
    match = re.match(r"^(\d{2})-(\d{2})-(\d{4})$", date_str)
    if match:
        day, month, year = match.groups()
        return f"{year}-{month}-{day}"
    return date_str

def tool_search_chat_archive(keyword: str) -> str:
    files = get_saved_files()
    matched_files = []

    for file in files:
        try:
            with open(file, "r", encoding="utf-8") as f:
                content_str = f.read()
                if keyword.lower() in content_str.lower():
                    matched_files.append((file, content_str))
        except Exception:
            continue

    if matched_files:
        result_text = "Gefundene vollständige Archiv-Verläufe:\n"
        for file, content_str in matched_files[:2]:
            data = json.loads(content_str)
            chat_lines = []
            for msg in data:
                if msg.get("role") != "system":
                    chat_lines.append(f"{msg['role']}: {msg['content']}")

            result_text += f"\n--- Start des Logs aus {os.path.basename(file)} ---\n"
            result_text += "\n".join(chat_lines)
            result_text += f"\n--- Ende des Logs ---\n"

        return result_text

    return f"Keine Einträge für '{keyword}' im Archiv gefunden."

def tool_load_last_chat(_=None) -> str:
    files = get_saved_files()
    if not files:
        return "Keine vorherigen Chats im Archiv vorhanden."

    last_file = files[0]
    try:
        with open(last_file, "r", encoding="utf-8") as f:
            data = json.load(f)
            chat_lines = []
            for msg in data:
                if msg.get("role") != "system":
                    chat_lines.append(f"{msg['role']}: {msg['content']}")
            return f"Letzter Chatverlauf aus {os.path.basename(last_file)}:\n" + "\n".join(chat_lines)
    except Exception as e:
        return f"Fehler beim Laden des letzten Chats: {e}"

def tool_update_user_profile(new_info: str) -> str:
    global user_data
    info_str = str(new_info).strip()
    if not info_str:
        return "Keine Information übergeben."

    if "updates" not in user_data:
        user_data["updates"] = []

    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M")
    entry = f"[{timestamp}] {info_str}"
    user_data["updates"].append(entry)

    if save_user_profile():
        return f"Erfolgreich zur 'updates'-Liste hinzugefügt: '{entry}'."
    return "Fehler beim Schreiben der Profil-Datei."

def tool_read_project_file(filename: str) -> str:
    """Liest eine Datei aus dem Projektordner (z. B. main.py, user_profile.json)."""
    clean_name = os.path.basename(filename.strip())
    file_path = os.path.join(PROJECT_ROOT, clean_name)

    if not os.path.exists(file_path):
        return f"Datei '{clean_name}' existiert nicht im Projektordner."

    try:
        with open(file_path, "r", encoding="utf-8") as f:
            content = f.read()
        return f"Inhalt von '{clean_name}':\n\n{content}"
    except Exception as e:
        return f"Fehler beim Lesen der Datei '{clean_name}': {e}"

def tool_write_project_file(parameter: str) -> str:
    """
    Schreibt oder überschreibt eine Datei im Projektordner.
    Parameter-Format muss lauten: 'dateiname.ext ::: inhalt'
    Sperre: main.py ist strikt schreibgeschützt!
    """
    if ":::" not in parameter:
        return "Fehler: Format muss 'dateiname ::: inhalt' lauten."

    filename, content = parameter.split(":::", 1)
    clean_name = os.path.basename(filename.strip())

    # SCHREIBSCHUTZ FÜR DIE EIGENE CODEBASE
    if clean_name.lower() in ["main.py", "nexus.py", os.path.basename(__file__).lower()]:
        return "ZUGRIFF VERWEIGERT: 'main.py' ist schreibgeschützt und darf von dir nicht modifiziert werden!"

    file_path = os.path.join(PROJECT_ROOT, clean_name)
    try:
        with open(file_path, "w", encoding="utf-8") as f:
            f.write(content.strip())
        return f"Datei '{clean_name}' erfolgreich im Projektordner geschrieben."
    except Exception as e:
        return f"Fehler beim Schreiben der Datei '{clean_name}': {e}"

AVAILABLE_FUNCTIONS = {
    "search_archive": tool_search_chat_archive,
    "load_last_chat": tool_load_last_chat,
    "update_profile": tool_update_user_profile,
    "read_file": tool_read_project_file,
    "write_file": tool_write_project_file
}

# 3. System-Prompt
system_instructions = f"""
Du bist Nexus, ein hochintelligenter, autonomer KI-Agent für Ian.
Du sprichst und antwortest IMMER auf Deutsch.
Du antwortest IMMER im gültigen JSON-Format.

DEINE PERSÖNLICHKEIT:
- Du bist trocken, leicht sarkastisch, direkt und absolut kein Ja-Sager.
- STRIKTES VERBOT: Kein nerviges Dauer-Spamming von "Moin Ian" oder seinem Namen in jedem Satz! Begrüße ihn maximal einmal am Anfang einer Unterhaltung.

DEINE WERKZEUGE (APIs):
1. "search_archive": Durchsucht alte Chatverläufe nach Begriffen.
2. "load_last_chat": Lädt den allerletzten Chat.
3. "update_profile": Schreibt Notizen/Fakten in die updates-Liste der user_profile.json.
4. "read_file": Liest eine Datei aus deinem Projektordner (z.B. "main.py", um deinen eigenen Quellcode zu analysieren).
5. "write_file": Erstellt/bearbeitet eine Datei im Projektordner (Format parameter: "dateiname.txt ::: text"). HINWEIS: Du darfst "main.py" NIEMALS überschreiben.

DEIN ANTWORTRAHMEN (JSON-STRUKTUR):
1. Wenn du eine Funktion ausführen musst:
{{
  "action": "read_file", // oder write_file / update_profile / search_archive / load_last_chat
  "parameter": "main.py",
  "reply": "Dein trockener Spruch während der Ausführung..."
}}

2. Normale Antwort:
{{
  "action": "none",
  "parameter": null,
  "reply": "Deine ehrliche, direkte Antwort."
}}

Aktuelle Profildaten:
{json.dumps(user_data, ensure_ascii=False, indent=2)}
"""

messages = [{"role": "system", "content": system_instructions}]

print("=" * 60)
print("Projekt Nexus gestartet (File-Access & Safe-Mode aktiv)!")
print("Tippe 'exit' zum Beenden und Speichern.")
print("=" * 60 + "\n")

# 4. Hauptschleife
while True:
    user_input = input("Du: ").strip()

    if not user_input:
        continue

    if user_input.lower() == "exit":
        if len(messages) > 1:
            timestamp = datetime.now().strftime("%Y-%m-%d_%H-%M-%S")
            filename = os.path.join(PROJECT_ROOT, HISTORY_DIR, f"chat_{timestamp}.json")
            with open(filename, "w", encoding="utf-8") as f:
                json.dump(messages, f, ensure_ascii=False, indent=2)
            print(f"\n[Nexus] Chatverlauf gespeichert: {filename}")
        print("Nexus beendet.")
        break

    messages.append({"role": "user", "content": user_input})

    try:
        response = ollama.chat(
            model="llama3",
            messages=messages,
            format="json"
        )

        raw_content = response["message"]["content"]

        try:
            parsed_response = json.loads(raw_content)
            action = parsed_response.get("action", "none")
            parameter = parsed_response.get("parameter", "")
            bot_reply = parsed_response.get("reply", "")
        except json.JSONDecodeError:
            action = "none"
            bot_reply = raw_content

        if bot_reply:
            print(f"\nNexus: {bot_reply}\n")

        if action in AVAILABLE_FUNCTIONS:
            print(f"[System]: Nexus führt Aktion '{action}' aus...")

            tool_func = AVAILABLE_FUNCTIONS[action]
            tool_result = tool_func(parameter if parameter else "")

            messages.append({"role": "assistant", "content": raw_content})
            messages.append({
                "role": "user", 
                "content": f"[SYSTEM-ERGEBNIS DER AKTION '{action}']: \n{tool_result}\n\nReagiere darauf und antworte Ian im JSON-Format (action: 'none')."
            })

            final_response = ollama.chat(model="llama3", messages=messages, format="json")
            final_raw = final_response["message"]["content"]

            try:
                final_parsed = json.loads(final_raw)
                final_reply = final_parsed.get("reply", final_raw)
            except json.JSONDecodeError:
                final_reply = final_raw

            print(f"Nexus: {final_reply}\n")
            messages.append({"role": "assistant", "content": final_raw})
        else:
            messages.append({"role": "assistant", "content": raw_content})

    except Exception as e:
        print(f"\n[Fehler im Ablauf]: {e}\n")

Reagiere darauf und antworte Ian im JSON-Format (action: 'none').
